// Expo config plugin: signs Android *release* builds with signing/keystore.properties.
// The android/ folder is generated by `expo prebuild`, so the change is re-applied every time.
const { withAppBuildGradle, withDangerousMod } = require('expo/config-plugins');
const fs = require('node:fs');
const path = require('node:path');

const LOADER = `
// --- Wallpepper release signing (plugins/withReleaseSigning.js) ---
def keystoreProps = new Properties()
def keystorePropsFile = rootProject.file('../signing/keystore.properties')
if (keystorePropsFile.exists()) {
    keystorePropsFile.withInputStream { keystoreProps.load(it) }
}
// ------------------------------------------------------------------

`;

const RELEASE_SIGNING = `
        if (keystorePropsFile.exists()) {
            release {
                storeFile rootProject.file('../' + keystoreProps['storeFile'])
                storePassword keystoreProps['storePassword']
                keyAlias keystoreProps['keyAlias']
                keyPassword keystoreProps['keyPassword']
            }
        }`;

// R8 strips the reflectively-instantiated Room database used by androidx.work (expo-background-task),
// crashing the release app at startup: NoSuchMethodException WorkDatabase_Impl.<init>.
const KEEP_RULES = `
# --- Wallpepper (plugins/withReleaseSigning.js) ---
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class androidx.work.impl.WorkDatabase_Impl { *; }
`;

function withKeepRules(config) {
  return withDangerousMod(config, [
    'android',
    (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      const cur = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
      if (!cur.includes('WorkDatabase_Impl')) fs.writeFileSync(file, cur + KEEP_RULES);
      return cfg;
    },
  ]);
}

module.exports = function withReleaseSigning(config) {
  config = withKeepRules(config);
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes('keystoreProps')) return cfg; // already applied

    // 1. load the properties file before the android { } block
    src = src.replace(/\nandroid \{/, `${LOADER}android {`);

    // 2. add the release signing config after the debug one
    src = src.replace(/(signingConfigs \{\s*debug \{[^}]*\})/, `$1${RELEASE_SIGNING}`);

    // 3. use it for the release build type (fall back to debug with a warning if the key is missing)
    src = src.replace(
      /(release \{\s*\/\/ Caution![^\n]*\n\s*\/\/ see [^\n]*\n\s*)signingConfig signingConfigs\.debug/,
      `$1if (keystorePropsFile.exists()) {
                signingConfig signingConfigs.release
            } else {
                logger.warn('WARNING: signing/keystore.properties not found - release build is signed with the DEBUG key')
                signingConfig signingConfigs.debug
            }`,
    );

    if (!src.includes('signingConfigs.release')) {
      throw new Error('withReleaseSigning: could not patch android/app/build.gradle (template changed?)');
    }
    cfg.modResults.contents = src;
    return cfg;
  });
};
